mapper.select:
SELECT COUNT(*)
  FROM emp01_person
 WHERE emp01_company_id = #{companyId}
   AND emp01_person_id  = #{personId}

mapper.update:
UPDATE emp20_leave
   SET emp20_over_confirm_status_cd = #{confirmStatusCode}
     , emp20_over_confirmer_id      = #{confirmerId}
     , emp20_over_confirm_date      = CASE WHEN #{confirmStatusCode} IN ('20','30') THEN f_sysdate() ELSE null END
 WHERE emp20_leave_id   = #{leaveId}
   AND emp20_company_id = #{companyId}

mapper.delete:
DELETE FROM sys99_print
 WHERE sys99_company_id      = #{companyId}
   AND sys99_person_id       = #{personId}
   AND sys99_window_class_nm = #{windowClassName}
